def experiment(inputs):
    import random
    def run_agent(persistence, seeds):
        state = [0.0] * 5
        for s in seeds:
            random.seed(s)
            noise = [random.random() for _ in range(5)]
            if persistence:
                state = [s1 + n for s1, n in zip(state, noise)]
            else:
                state = noise
        norm = sum(x*x for x in state)**0.5
        return [x/norm for x in state] if norm > 0 else state
    s1 = inputs['seeds'][0]
    s2 = inputs['seeds'][1]
    v_persist = run_agent(True, [s1, s2])
    v_no_persist = run_agent(False, [s1, s2])
    dot = sum(a*b for a, b in zip(v_persist, v_no_persist))
    return {'divergence_score': 1.0 - dot}
